typedef float rational_t;
typedef float time_value_t;
typedef unsigned long uint64;

class ai_interface;
class ai_action;
class chunk_file;
class stringx;

union alloc_object {
    alloc_object *next;
    char data[1];
};

struct allocator_layout {
    alloc_object *free_list[16];
};

extern allocator_layout allocator_pool;
extern void *allocator_refill(unsigned int);
__asm__(".equ allocator_pool, 0x003E5628");
__asm__(".equ allocator_refill, 0x0010DAE0");

template<class T>
class list {
    struct node {
        node *next;
        node *previous;
        T value;
    };

    node *head;

public:
    list()
    {
        alloc_object *raw = allocator_pool.free_list[1];
        if (!raw)
            raw = (alloc_object *)allocator_refill(sizeof(node));
        else
            allocator_pool.free_list[1] = raw->next;

        head = (node *)raw;
        head->next = head;
        head->previous = head;
    }
};

class pstring {
    uint64 pchunk[4];
    void pack_string(const char *);

public:
    pstring(const char *target_string)
    {
        pack_string(target_string);
    }

    pstring &operator=(const pstring &new_guy)
    {
        if (&new_guy == this)
            return *this;

        for (unsigned i = 0; i < 4; ++i)
            pchunk[i] = new_guy.pchunk[i];
        return *this;
    }
};

__asm__(".equ pack_string__7pstringPCc, 0x003354D0");
extern const char ai_goal_vtable[];
__asm__(".equ ai_goal_vtable, 0x004C83A0");

class ai_goal {
protected:
    ai_interface *owner;
    rational_t priority;
    rational_t priority_modifier;
    bool in_service;
    list<ai_action *> actions;
    pstring type;

    virtual rational_t frame_advance(time_value_t t);
    virtual ai_goal *make_copy(ai_interface *own) = 0;
    virtual void dump_actions();
    virtual void dump_action(ai_action *act);
    void read_data(chunk_file &fs);
    virtual void handle_chunk(chunk_file &fs, stringx &label);

public:
    ai_goal(ai_interface *own);
    virtual ~ai_goal();
    virtual rational_t calculate_priority(time_value_t t) = 0;
    virtual void going_into_service();
    virtual void going_out_of_service();
    virtual unsigned int add_action(ai_action *act);
    virtual bool running_action(unsigned int id);
    virtual void dump_action(unsigned int id);
};

ai_goal::ai_goal(ai_interface *own)
{
  owner = own;
  priority = 0.0f;
  priority_modifier = 1.0f;
  in_service = false;

  type = pstring("NONE");
}
